#include <iostream>
bool valid(int price, int qty) {
    return price >= 0 && price <= 1000 && qty >= 0 && qty <= 1000;
}
int subtotal(int price, int qty) {
    return price * qty;
}
int main() {
    int price, qty;
    if (!(std::cin >> price >> qty)) { std::cout << "invalid\n"; return 0; }
    if (!valid(price, qty)) { std::cout << "invalid\n"; return 0; }
    std::cout << subtotal(price, qty) << '\n';
}

